import { Suspense } from 'react'

async function getAnalytics() {
  const res = await fetch('/api/analytics')
  return res.json()
}

async function getNotifications() {
  const res = await fetch('/api/notifications')
  return res.json()
}

async function getSettings() {
  const res = await fetch('/api/settings')
  return res.json()
}

async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      getAnalytics(),
      getNotifications(),
      getSettings(),
    ])

    return { analytics, notifications, settings }
  } catch {
    return {
      analytics: { views: 0, visitors: 0, bounceRate: 0 },
      notifications: [],
      settings: { theme: 'light', language: 'en' },
    }
  }
}

function AnalyticsCard({
  analytics,
}: {
  analytics: { views: number; visitors: number; bounceRate: number }
}) {
  return (
    <div style={{ border: '1px solid #ccc', padding: '1rem', borderRadius: '8px' }}>
      <h3>Analytics</h3>
      <p>Views: {analytics.views}</p>
      <p>Visitors: {analytics.visitors}</p>
      <p>Bounce Rate: {analytics.bounceRate}%</p>
    </div>
  )
}

function NotificationsList({
  notifications,
}: {
  notifications: { id: string; message: string; read: boolean }[]
}) {
  return (
    <div style={{ border: '1px solid #ccc', padding: '1rem', borderRadius: '8px' }}>
      <h3>Notifications</h3>
      {notifications.length === 0 ? (
        <p>No new notifications</p>
      ) : (
        <ul>
          {notifications.map((notification) => (
            <li key={notification.id}>
              {notification.message}
              {!notification.read && ' (unread)'}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

function SettingsPanel({
  settings,
}: {
  settings: { theme: string; language: string }
}) {
  return (
    <div style={{ border: '1px solid #ccc', padding: '1rem', borderRadius: '8px' }}>
      <h3>Settings</h3>
      <p>Theme: {settings.theme}</p>
      <p>Language: {settings.language}</p>
    </div>
  )
}

function DashboardFallback() {
  return (
    <div>
      <h2>Dashboard Content</h2>
      <p>Loading dashboard data...</p>
    </div>
  )
}

async function DashboardContent() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
      <AnalyticsCard analytics={analytics} />
      <NotificationsList notifications={notifications} />
      <SettingsPanel settings={settings} />
    </div>
  )
}

export default async function Dashboard() {
  return (
    <Suspense fallback={<DashboardFallback />}>
      <DashboardContent />
    </Suspense>
  )
}

